<?php

use Illuminate\Validation\ValidationException;
use Mothership\DAM\Services\ImageEditorSchema;

/*
 * Schema v2 is PhotoEdit's document. tests/Fixtures/photoedit/schema-v2-cases.json holds, for each case, the
 * verdict and export size that PhotoEdit's own validateDocument() and outputSize() computed (generated by
 * tests/js/photoedit-schema-cases.mjs, which a JS test keeps current). The server must agree on every one,
 * since a document the browser exports but the server refuses, or a render of another size, loses the user's save.
 */

function schemaV2Cases(): array
{
    return json_decode(file_get_contents(__DIR__.'/../Fixtures/photoedit/schema-v2-cases.json'), true, 512, JSON_THROW_ON_ERROR);
}

/** What the server says about a document's JSON: [accepted, width, height]. */
function schemaV2Verdict(string $json): array
{
    $schema = app(ImageEditorSchema::class);
    try {
        $document = $schema->decode($json);
        $schema->validate($document);
        [$width, $height] = $schema->dimensions($document);

        return [true, $width, $height];
    } catch (ValidationException) {
        return [false, null, null];
    }
}

it('agrees with PhotoEdit on whether each schema v2 document is valid and how large its export is', function () {
    $cases = schemaV2Cases();
    $disagreements = [];
    foreach ($cases as $case) {
        [$accepted, $width, $height] = schemaV2Verdict($case['json']);
        if ($accepted !== $case['valid'] || ($accepted && [$width, $height] !== [$case['width'], $case['height']])) {
            $disagreements[] = $case['name'].' => server '.json_encode([$accepted, $width, $height]).', PhotoEdit '.json_encode([$case['valid'], $case['width'], $case['height']]);
        }
    }

    expect(count($cases))->toBeGreaterThan(1000)
        ->and($disagreements)->toBe([]);
});

it('covers sizes where the aspect ratio rounds, so parity is not only integers', function () {
    $sizes = collect(schemaV2Cases())->where('valid', true)->filter(fn ($case) => str_starts_with($case['name'], 'size: half rounds'))
        ->mapWithKeys(fn ($case) => [$case['name'] => [$case['width'], $case['height']]])->all();

    // 20x101 into 1:2 is 50.5 wide, which a browser rounds up.
    expect($sizes)->toBe(['size: half rounds up wide' => [51, 101], 'size: half rounds up tall' => [101, 51]]);
});

it('names every image a document uses, so ownership is checked for all of them', function () {
    $schema = app(ImageEditorSchema::class);
    $document = json_decode(collect(schemaV2Cases())->firstWhere('name', 'valid: every object type at once')['json'], true);
    $document['background']['image'] = '22222222-2222-4222-8222-222222222222';
    $document['objects'][] = ['id' => 'second', 'type' => 'image', 'x' => 0, 'y' => 0, 'width' => 5, 'height' => 5, 'resource' => '44444444-4444-4444-8444-444444444444'];
    $document['objects'][] = ['id' => 'again', 'type' => 'image', 'x' => 0, 'y' => 0, 'width' => 5, 'height' => 5, 'resource' => '44444444-4444-4444-8444-444444444444'];

    expect($schema->resourceIds($document))->toBe([
        '11111111-1111-4111-8111-111111111111',
        '22222222-2222-4222-8222-222222222222',
        '33333333-3333-4333-8333-333333333333',
        '44444444-4444-4444-8444-444444444444',
    ]);

    // Ids the schema allows are never dropped for being falsy, so ownership is checked on every one.
    $document['objects'][] = ['id' => 'zero', 'type' => 'image', 'x' => 0, 'y' => 0, 'width' => 5, 'height' => 5, 'resource' => '0'];
    $document['background']['image'] = '';
    expect($schema->resourceIds($document))->toContain('0', '');
});

it('keeps accepting schema v1 and its 8192-pixel, 32-megapixel output limit', function () {
    $schema = app(ImageEditorSchema::class);
    $v1 = $schema->initial('11111111-1111-4111-8111-111111111111', 400, 300);

    expect($schema->validate($v1))->toBe($v1)
        ->and($schema->dimensions($v1))->toBe([400, 300])
        ->and($schema->renderLimits($v1))->toBe(['side' => 8192, 'pixels' => 32000000]);

    $tooWide = $schema->initial('11111111-1111-4111-8111-111111111111', 8192, 100);
    $tooWide['background']['enabled'] = true;
    $tooWide['background']['padding'] = 40;
    expect(fn () => $schema->validate($tooWide))->toThrow(ValidationException::class);
});

it('lets only a schema v2 render exceed the v1 output limits', function () {
    $schema = app(ImageEditorSchema::class);
    $wide = json_decode(collect(schemaV2Cases())->firstWhere('name', 'budget ok: 16380 wide by a 20:1 ratio')['json'], true);

    expect($schema->validate($wide))->toBe($wide)
        ->and($schema->dimensions($wide))->toBe([16380, 819])
        ->and($schema->renderLimits($wide))->toBe(['side' => 16384, 'pixels' => 64000000]);
});
